		// both are `Signer` + `#[account(mut)]` on the bridge program.
		accounts__.Append(solanago.NewAccountMeta(poolSignerAccount, true, false))
		// Account 6 "pool_token_account": Writable, Non-signer, Required
		// The custody account `lock_or_burn_tokens_v2` left the (post-fee) tokens in; this is what
		// `bridge::deposit` actually burns from.
		accounts__.Append(solanago.NewAccountMeta(poolTokenAccountAccount, true, false))
		// Account 7 "bridge": Read-only, Non-signer, Required, Address: Lomva5kTftuXE8992qRufkaeq3XrXV47qv3C1W9xW6Z
		accounts__.Append(solanago.NewAccountMeta(bridgeAccount, false, false))
