		// Account 9 "bridge_sender_config": Read-only, Non-signer, Required
		accounts__.Append(solanago.NewAccountMeta(bridgeSenderConfigAccount, false, false))
		// Account 10 "remote_bridge_config": Read-only, Non-signer, Required
		accounts__.Append(solanago.NewAccountMeta(remoteBridgeConfigAccount, false, false))
		// Account 11 "local_token_config": Read-only, Non-signer, Required
		accounts__.Append(solanago.NewAccountMeta(localTokenConfigAccount, false, false))
		// Account 12 "remote_token_config": Read-only, Non-signer, Required
		accounts__.Append(solanago.NewAccountMeta(remoteTokenConfigAccount, false, false))
		// Account 13 "mailbox": Read-only, Non-signer, Required
		accounts__.Append(solanago.NewAccountMeta(mailboxAccount, false, false))
		// Account 14 "mailbox_config": Writable, Non-signer, Required
		accounts__.Append(solanago.NewAccountMeta(mailboxConfigAccount, true, false))
		// Account 15 "outbound_message_path": Read-only, Non-signer, Required
		accounts__.Append(solanago.NewAccountMeta(outboundMessagePathAccount, false, false))
		// Account 16 "outbound_message": Writable, Non-signer, Required
		accounts__.Append(solanago.NewAccountMeta(outboundMessageAccount, true, false))
		// Account 17 "mailbox_sender_config": Read-only, Non-signer, Required
		accounts__.Append(solanago.NewAccountMeta(mailboxSenderConfigAccount, false, false))
		// Account 18 "treasury": Writable, Non-signer, Optional
		accounts__.Append(solanago.NewAccountMeta(treasuryAccount, true, false))
		// Account 19 "system_program": Read-only, Non-signer, Required
		accounts__.Append(solanago.NewAccountMeta(systemProgramAccount, false, false))
